message.content:
I replaced the two-nibble lookup chain with a single 256-entry byte table (the equivalent reflected CRC-16/IBM table, generated at compile time), cutting the per-byte work to one table load plus a shift/xor.

```include
#include <array>
```

```cpp
FIT_UINT16 CRC::Get16(FIT_UINT16 crc, FIT_UINT8 byte)
{
   static constexpr std::array<FIT_UINT16, 256> crc_table = []() constexpr
   {
      std::array<FIT_UINT16, 256> t{};
      for (int i = 0; i < 256; ++i)
      {
         FIT_UINT16 c = static_cast<FIT_UINT16>(i);
         for (int j = 0; j < 8; ++j)
            c = (c & 1) ? static_cast<FIT_UINT16>((c >> 1) ^ 0xA001)
                        : static_cast<FIT_UINT16>(c >> 1);
         t[i] = c;
      }
      return t;
   }();

   return static_cast<FIT_UINT16>((crc >> 8) ^ crc_table[(crc ^ byte) & 0xFF]);
}
```
